  actionBox=box(x,131,fieldW,actionText,action.parameter());button(x+fieldW+4,131,wide-fieldW-4,"+ Add action",()->{capture();try{var trial=new java.util.ArrayList<>(steps);trial.add(new LuaAuthoring.Step(actionIndex,actionText));LuaAuthoring.generate(eventIndex,condition,conditionText,Double.parseDouble(delayText),trial,ruleId);steps.add(new LuaAuthoring.Step(actionIndex,actionText));status=steps.size()+" action(s) ready";updateRulePreview();}catch(Exception e){status=e.getMessage();}});
  button(x,153,54,"Delay (s)",()->{}).active=false;delayBox=box(x+58,153,40,delayText,"Delay in seconds; 0 = immediate");button(x+102,153,wide-102,"Insert rule into script",this::insertRule);
  button(x,175,wide/2-2,"Clear actions",()->{steps.clear();updateRulePreview();});button(x+wide/2+2,175,wide/2-2,"Preview Lua",this::previewRule).setTooltip(Tooltip.create(Component.literal("Insert the rule to include it in the editable script.")));
  if(contentWidth>450){rulePreview=addRenderableWidget(new MultiLineEditBox(font,other,65,contentWidth-wide-10,Math.max(60,height-108),Component.empty(),Component.literal("Rule preview")));updateRulePreview();}
