 private void choose(String title,java.util.List<Integer> choices,java.util.function.IntFunction<String> label,java.util.function.IntFunction<String> hint,java.util.function.IntConsumer selected){capture();var owner=this;minecraft.setScreen(new Screen(Component.literal(title)){int choicePage;@Override protected void init(){int count=Math.max(1,(height-80)/25),y=40;for(int index:choices.stream().skip(choicePage*(long)count).limit(count).toList()){addRenderableWidget(Button.builder(Component.literal(label.apply(index)),b->{selected.accept(index);owner.editor=null;minecraft.setScreen(owner);}).bounds(20,y,width-40,21).tooltip(Tooltip.create(Component.literal(hint.apply(index)))).build());y+=25;}addRenderableWidget(Button.builder(Component.literal("<"),b->{choicePage=Math.max(0,choicePage-1);rebuildWidgets();}).bounds(20,height-28,40,20).build());addRenderableWidget(Button.builder(Component.literal(">"),b->{if((choicePage+1)*count<choices.size())choicePage++;rebuildWidgets();}).bounds(64,height-28,40,20).build());addRenderableWidget(Button.builder(Component.literal("Back"),b->onClose()).bounds(width-100,height-28,80,20).build());}@Override public void render(GuiGraphics g,int x,int y,float partial){g.fill(0,0,width,height,0xFF10151D);g.drawCenteredString(font,this.title,width/2,14,0xE0EAF2);super.render(g,x,y,partial);}@Override public void onClose(){minecraft.setScreen(owner);}@Override public boolean isPauseScreen(){return false;}});}
 private void previewRule(){capture();try{String code=generated();var owner=this;minecraft.setScreen(new Screen(Component.literal("Generated Lua")){@Override protected void init(){addRenderableWidget(new MultiLineEditBox(font,12,35,width-24,height-76,Component.empty(),Component.literal("Generated Lua"))).setValue(code);addRenderableWidget(Button.builder(Component.literal("Insert into script"),b->{minecraft.setScreen(owner);owner.insertRule();}).bounds(width/2-124,height-28,120,20).build());addRenderableWidget(Button.builder(Component.literal("Back"),b->minecraft.setScreen(owner)).bounds(width/2+4,height-28,120,20).build());}@Override public void render(GuiGraphics g,int x,int y,float p){g.fill(0,0,width,height,0xFF10151D);g.drawCenteredString(font,title,width/2,12,0xE0EAF2);super.render(g,x,y,p);}@Override public boolean isPauseScreen(){return false;}@Override public void onClose(){minecraft.setScreen(owner);}});}catch(Exception e){status=e.getMessage();}}
 private String generated(){return LuaAuthoring.generate(eventIndex,condition,conditionText,Double.parseDouble(delayText),steps,ruleId);}
 private void updateRulePreview(){capture();if(rulePreview!=null){String text="GUIDED RULE\n\n"+LuaAuthoring.EVENTS.get(eventIndex).help()+"\n\n";for(int i=0;i<steps.size();i++){var step=steps.get(i);text+=(i+1)+". "+LuaAuthoring.ACTIONS.get(step.action()).label()+": "+step.value()+"\n";}try{text+="\n"+generated();}catch(Exception e){text+="\n"+e.getMessage();}rulePreview.setValue(text);}}
 private void insertRule(){capture();try{String code=generated();editor.setValue(document+code);document=editor.getValue();ruleId=java.util.UUID.randomUUID().toString().replace("-","").substring(0,12);status="Rule appended. Check, then Save. Existing Lua stays editable.";changeMode(1);}catch(Exception e){status=e.getMessage();}}
 private void buildHelp(){api=box(left+4,65,contentWidth,query,"Search API: atmosphere, voice, points, timer...");help=addRenderableWidget(new SelectableTextBox(left+4,89,contentWidth,Math.max(30,height-167),true));api.setResponder(v->{query=v;help.setValue(String.join("\n\n",LuaWorkbench.reference(v)));});help.setValue(String.join("\n\n",LuaWorkbench.reference(query)));int w=(contentWidth-8)/3;button(left+4,height-61,w,"Copy example",()->{var example=LuaWorkbench.example(query);if(example.isEmpty()){status="Search a documented method with an example first.";return;}minecraft.keyboardHandler.setClipboard(example);status="Example copied. Paste it in Code or another editor.";});button(left+8+w,height-61,w,"Copy selection",()->{var selected=((SelectableTextBox)help).field().getSelectedText();if(selected.isEmpty()){status="Drag over the documentation to select text first.";return;}minecraft.keyboardHandler.setClipboard(selected);status="Selected documentation copied.";});button(left+12+w*2,height-61,contentWidth-w*2-8,"Insert example",()->{var example=LuaWorkbench.example(query);if(example.isEmpty()){status="Search a documented method first.";return;}editor.field().insertText("\n"+example+"\n");document=editor.getValue();codeCursor=editor.field().cursor();codeAnchor=codeCursor;changeMode(1);setFocused(editor);});}
 private void discard(Runnable action){capture();if(document.equals(saved))action.run();else minecraft.setScreen(new ConfirmScreen(ok->{minecraft.setScreen(this);if(ok)action.run();},Component.literal("Unsaved script"),Component.literal("Discard changes? Use Save to keep this script.")));}
 private void request(String action){capture();if(action.equals("save"))sent=document;me.cryo.zombierool.network.NetworkHandler.INSTANCE.sendToServer(new LuaWorkbenchPackets.Request(action,name,action.equals("save")||action.equals("run")||action.equals("validate")?document:"",version));}
 public void response(CompoundTag n){String action=n.getString("action");if(!n.getBoolean("success")){diagnostic(n.getString("message"));return;}if(action.equals("list")){var list=n.getList("files",8);var incoming=new java.util.ArrayList<String>();for(int i=0;i<list.size();i++)incoming.add(list.getString(i));if(!files.equals(incoming)){files=incoming;rebuildWidgets();}}else if(action.equals("read")&&name.equals(n.getString("name"))){document=n.getString("code");version=n.getString("version");saved=document;editor.setValue(document);changeMode(1);status="Opened "+name;}else if(action.equals("save")&&name.equals(n.getString("name"))){version=n.getString("version");saved=sent;status="Saved. This does not execute the script.";request("list");}else if(action.equals("console")){if(console!=null){var lines=n.getList("lines",8);var text=new StringBuilder();for(int i=0;i<lines.size();i++)text.append(lines.getString(i)).append('\n');console.setValue(text.toString());}}else diagnostic(n.getString("message"));}
 private void diagnostic(String text){status=text;errorLine=-1;var match=java.util.regex.Pattern.compile(":(\\d+):").matcher(text);if(match.find()){errorLine=Integer.parseInt(match.group(1));if(mode==1){int pos=0;for(int i=1;i<errorLine&&pos<editor.getValue().length();i++){int next=editor.getValue().indexOf('\n',pos);if(next<0)break;pos=next+1;}editor.field().setSelecting(false);editor.field().seekCursor(Whence.ABSOLUTE,pos);setFocused(editor);}}}
 private void find(){if(findText.isEmpty())return;var f=editor.field();String value=editor.getValue();int index=value.indexOf(findText,f.cursor());if(index<0)index=value.indexOf(findText);if(index>=0){f.setSelecting(false);f.seekCursor(Whence.ABSOLUTE,index);f.setSelecting(true);f.seekCursor(Whence.ABSOLUTE,index+findText.length());f.setSelecting(false);}else status="No match";}
 @Override public void tick(){editor.tick();filename.tick();if(mode==3&&++ticks%30==0)request("console");}
 @Override public boolean keyPressed(int key,int scan,int mods){if(hasControlDown()&&key==83){request("save");return true;}if(key==294){request("validate");return true;}return super.keyPressed(key,scan,mods);}
 @Override public void onClose(){discard(()->minecraft.setScreen(parent));}@Override public boolean isPauseScreen(){return false;}
 @Override public void render(GuiGraphics g,int mx,int my,float partial){renderBackground(g);g.fill(0,0,width,height,0xFF10151D);g.fill(0,0,left-2,height-28,0xFF18212B);g.fill(left,34,width-8,59,0xFF202D3B);g.drawString(font,"SCRIPT",8,12,0x8BBEE0);g.drawString(font,"Files",8,63,0x93A9BD);super.render(g,mx,my,partial);if(mode==1)editor.renderLineNumbers(g);String message=status.isEmpty()?(mode==0?"Build a rule, insert it, then check and save.":mode==1?"Ctrl+S Save   F5 Check   Ctrl+Space API completion   Ctrl+Z Undo   F1 Help":"Help and console never execute code."):status;g.drawString(font,font.plainSubstrByWidth(message,width-20),10,height-34,errorLine>0?0xFF9988:0xA7BDD0);if(mode==1){int cursor=editor.field().cursor();int line=1;for(int i=0;i<cursor;i++)if(editor.getValue().charAt(i)=='\n')line++;g.drawString(font,"Ln "+line+(editor.getValue().equals(saved)?"":"  *"),8,26,0xA6B8C9);}}
 // MultiLineEditBox returns early when AbstractScrollWidget consumes a content click.
 // Resolve text coordinates first; leave scrollbar handling to the vanilla widget.
 private class SelectableTextBox extends CodeEditorBox {
  private final boolean readOnly;private boolean selectingWithMouse;
  SelectableTextBox(int x,int y,int w,int h,boolean readOnly){super(LuaWorkbenchScreen.this.font,x,y,w,h,Component.empty(),Component.literal(readOnly?"API documentation":"Lua editor"));this.readOnly=readOnly;setCharacterLimit(120000);}
  MultilineTextField field(){return net.minecraftforge.fml.util.ObfuscationReflectionHelper.getPrivateValue(MultiLineEditBox.class,this,"f_238540_");}
  private void point(double x,double y){field().seekCursorToPoint(x-getX()-innerPadding(),y-getY()-innerPadding()+scrollAmount());}
  @Override public boolean mouseClicked(double x,double y,int button){if(!visible||!active)return false;if(button==0&&withinContentAreaPoint(x,y)){field().setSelecting(hasShiftDown());point(x,y);field().setSelecting(false);selectingWithMouse=true;return true;}return super.mouseClicked(x,y,button);}
  @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(button==0&&selectingWithMouse){if(y<getY())setScrollAmount(scrollAmount()-9);else if(y>getY()+getHeight())setScrollAmount(scrollAmount()+9);field().setSelecting(true);point(x,Math.max(getY()+innerPadding(),Math.min(getY()+getHeight()-innerPadding(),y)));field().setSelecting(false);return true;}return super.mouseDragged(x,y,button,dx,dy);}
  @Override public boolean mouseReleased(double x,double y,int button){selectingWithMouse=false;return super.mouseReleased(x,y,button);}
  @Override public boolean charTyped(char c,int mods){return !readOnly&&super.charTyped(c,mods);}
  @Override public boolean keyPressed(int key,int scan,int mods){if(readOnly&&!Screen.isCopy(key)&&!Screen.isSelectAll(key)&&!(key>=262&&key<=269)&&key!=340&&key!=344)return false;return super.keyPressed(key,scan,mods);}
 }
 private final class CodeBox extends SelectableTextBox {
  private final java.util.ArrayDeque<String> past=new java.util.ArrayDeque<>(),future=new java.util.ArrayDeque<>();private boolean restoring;private String previous="";
  CodeBox(int x,int y,int w,int h){super(x,y,w,h,false);setCharacterLimit(120000);setValueListener(v->{if(!restoring&&!v.equals(previous)){if(past.size()>=100)past.removeFirst();past.addLast(previous);future.clear();}previous=v;});}
  void selectLineIfEmpty(){if(field().hasSelection())return;int cursor=field().cursor(),start=getValue().lastIndexOf('\n',Math.max(-1,cursor-1))+1,end=getValue().indexOf('\n',cursor);if(end<0)end=getValue().length();else end++;field().seekCursor(Whence.ABSOLUTE,start);field().setSelecting(true);field().seekCursor(Whence.ABSOLUTE,end);field().setSelecting(false);}
  String copyText(){if(field().hasSelection())return field().getSelectedText();int cursor=field().cursor(),start=getValue().lastIndexOf('\n',Math.max(-1,cursor-1))+1,end=getValue().indexOf('\n',cursor);return getValue().substring(start,end<0?getValue().length():end+1);}
  void undo(){if(past.isEmpty())return;future.addLast(getValue());restoring=true;setValue(past.removeLast());restoring=false;}
  void redo(){if(future.isEmpty())return;past.addLast(getValue());restoring=true;setValue(future.removeLast());restoring=false;}
  @Override public boolean keyPressed(int key,int scan,int mods){if(key==290){String before=getValue().substring(0,field().cursor());var match=java.util.regex.Pattern.compile("ZombieroolAPI:([A-Za-z_][A-Za-z_0-9]*)").matcher(before);String method="";while(match.find())method=match.group(1);query=method;changeMode(2);return true;}if(hasControlDown()&&key==90){undo();return true;}if(hasControlDown()&&key==89){redo();return true;}if(hasControlDown()&&key==32){var f=field();String before=getValue().substring(0,f.cursor());var m=java.util.regex.Pattern.compile("[A-Za-z_][A-Za-z_0-9]*$").matcher(before);if(m.find()){String prefix=m.group();var candidates=java.util.Arrays.stream(ZombieroolAPI.class.getDeclaredMethods()).filter(method->java.lang.reflect.Modifier.isPublic(method.getModifiers())).map(java.lang.reflect.Method::getName).distinct().filter(n->n.startsWith(prefix)).sorted().toList();if(candidates.size()==1){f.deleteText(-prefix.length());f.insertText(candidates.get(0)+"(");}status=candidates.isEmpty()?"No API match":String.join(", ",candidates);}return true;}if(key==258){field().insertText("    ");return true;}if(key==257){var f=field();String before=getValue().substring(0,f.cursor());String line=before.substring(before.lastIndexOf('\n')+1);String indent=line.substring(0,line.length()-line.stripLeading().length());String trim=line.stripTrailing();if(trim.endsWith("then")||trim.endsWith("do")||trim.startsWith("function "))indent+="    ";f.insertText("\n"+indent);return true;}return super.keyPressed(key,scan,mods);}
 }
